def create_password_devices(apps: Apps, schema_editor: BaseDatabaseSchemaEditor):
    """Copy each usable password to a password device."""
    db_alias = schema_editor.connection.alias
    User = apps.get_model("authentik_core", "User")
    PasswordDevice = apps.get_model("authentik_stages_password", "PasswordDevice")

    users = (
        User.objects.using(db_alias)
        .exclude(password="")
        .exclude(password__startswith=UNUSABLE_PASSWORD_PREFIX)
        .only("password", "password_change_date")
    )
    print("\nMoving passwords to password devices, this might take a couple of minutes...")
    for batch in batched(chunked_queryset(users), 1_000, strict=False):
        PasswordDevice.objects.using(db_alias).bulk_create(
            PasswordDevice(
                user=user,
                name="Password",
                password=user.password,
                password_change_date=user.password_change_date,
            )
            for user in batch
        )


